package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
import static com.oms.order.service.ExchangeService.object;
import static com.ruoyi.common.core.constant.SecurityConstants.INNER;

/** Incremental query-only projection. Versioned markers survive concurrent updates and failures. */
@Service public class ReturnQueryProjection {
    @Resource OrderRepository repository;
    @Resource ReturnQueryClient warehouse;
    private org.springframework.transaction.support.TransactionTemplate tx(){return new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(repository.db().getDataSource()));}
    private static final List<String> FIELDS=Arrays.asList("company_code","view_kind","group_key","source_key","part_key","owner_kind","owner_id","owner_sn","source_id","channel_id","order_id","order_sn","platform_tid","platform_oid","sku_sn","goods_name","unit","is_gift","refund_only","return_mode","store_code","real_store_code","owner_code","original_shipment_sn","outbound_waybills","carrier","waybill","parcel_key","parcel_sn","return_sn","ticket_id","dispatch_after","quantity","quantity_known","accepted_quantity","posted_quantity","waived_quantity","pending_count","needs_check","active","dispatched","warehouse_state","interaction_result","receipt_difference","expected_members","message","snapshot","create_time");
    private String marks(Collection<?> ids){return String.join(",",Collections.nCopies(ids.size(),"?"));}
    private List<Object> args(String c,Collection<?> ids){List<Object> a=new ArrayList<>();a.add(c);a.addAll(ids);return a;}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> maps(Object raw){return raw instanceof List?(List<Map<String,Object>>)raw:Collections.emptyList();}
    public Map<String,Object> refresh(String c){
        List<Map<String,Object>> remote=Collections.emptyList(),claimed=Collections.emptyList();String lease=UUID.randomUUID().toString().replace("-","");String warning="";
        try{
            remote=data(warehouse.changes(c,INNER));Map<String,Long> remoteOwners=new HashMap<>();Set<Long> planIds=new LinkedHashSet<>();for(Map<String,Object> x:remote)if("REFUND".equals(x.get("owner_kind")))planIds.add(number(x,"source_id"));
            Map<Long,Long> refundByPlan=new HashMap<>();if(!planIds.isEmpty())for(Map<String,Object> p:repository.db().query("SELECT id,refund_id FROM oms_refund_return_plan WHERE company_code=? AND id IN ("+marks(planIds)+")",ROW,args(c,planIds).toArray()))refundByPlan.put(number(p,"id"),number(p,"refund_id"));
            List<Object[]> notifications=new ArrayList<>();for(Map<String,Object> x:remote){String k=text(x,"owner_kind");long owner="REFUND".equals(k)?refundByPlan.getOrDefault(number(x,"source_id"),0L):number(x,"source_id");remoteOwners.put(k+":"+number(x,"source_id"),owner);if(owner>0)notifications.add(new Object[]{c,k,owner});}
            if(!notifications.isEmpty())repository.db().batchUpdate("INSERT INTO oms_return_query_dirty(company_code,owner_kind,owner_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE work_version=work_version+1",notifications);
            claimed=tx().execute(tx->{List<Map<String,Object>> work=repository.db().query("SELECT owner_kind,owner_id,work_version FROM oms_return_query_dirty WHERE company_code=? AND (lease_until IS NULL OR lease_until<NOW()) ORDER BY owner_kind,owner_id LIMIT 20 FOR UPDATE",ROW,c);for(Map<String,Object> x:work)repository.db().update("UPDATE oms_return_query_dirty SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND owner_kind=? AND owner_id=?",lease,c,x.get("owner_kind"),x.get("owner_id"));return work;});
            if(!claimed.isEmpty())rebuild(c,claimed,lease);
            Set<String> processed=new HashSet<>();for(Map<String,Object> x:claimed)processed.add(x.get("owner_kind")+":"+x.get("owner_id"));List<Map<String,Object>> ack=new ArrayList<>();for(Map<String,Object> x:remote){long owner=remoteOwners.get(x.get("owner_kind")+":"+x.get("source_id"));if(owner==0||processed.contains(x.get("owner_kind")+":"+owner))ack.add(x);}if(!ack.isEmpty())data(warehouse.acknowledge(c,ack,INNER));
        }catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger(ReturnQueryProjection.class).warn("Return query projection unavailable for {}",c,e);warning=e instanceof IllegalArgumentException?String.valueOf(e.getMessage()):"仓库查询进度暂不可用，保留最近查询结果，请稍后刷新";repository.db().update("UPDATE oms_return_query_dirty SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND lease_token=?",c,lease);}
        long pending=repository.db().queryForObject("SELECT COUNT(*) FROM oms_return_query_dirty WHERE company_code=?",Long.class,c);
        if(pending==0&&remote.size()==100&&warning.isEmpty())try{pending=data(warehouse.changes(c,INNER)).size();}catch(RuntimeException unavailable){warning="仓库查询进度暂不可用，请稍后刷新";}
        return map("pending",pending,"updating",pending>0,"warning",warning);
    }
    void rebuild(String c,List<Map<String,Object>> claimed,String lease){
        Set<Long> refunds=new LinkedHashSet<>(),exchanges=new LinkedHashSet<>();for(Map<String,Object> w:claimed)("REFUND".equals(w.get("owner_kind"))?refunds:exchanges).add(number(w,"owner_id"));
        List<Map<String,Object>> tasks=new ArrayList<>();if(!refunds.isEmpty())refundTasks(c,refunds,tasks);if(!exchanges.isEmpty())exchangeTasks(c,exchanges,tasks);attachOutbound(c,tasks);
        require(tasks.size()<=2000,"本批退回来源超过2000项，请核对异常重复安排");List<Map<String,Object>> requests=new ArrayList<>();for(Map<String,Object> t:tasks)if(number(t,"source_id")>0)requests.add(map("owner_kind",t.get("owner_kind"),"source_id",t.get("source_id")));
        Map<String,List<Map<String,Object>>> actual=new HashMap<>();for(int at=0;at<requests.size();at+=250)for(Map<String,Object> x:data(warehouse.snapshots(c,requests.subList(at,Math.min(at+250,requests.size())),INNER)))actual.computeIfAbsent(x.get("owner_kind")+":"+x.get("source_id"),k->new ArrayList<>()).add(x);
        List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> t:tasks)project(c,t,actual.getOrDefault(t.get("owner_kind")+":"+t.get("source_id"),Collections.emptyList()),rows);
        tx().execute(tx->{
            for(Map<String,Object> w:claimed){Map<String,Object> current=repository.db().queryForMap("SELECT lease_token FROM oms_return_query_dirty WHERE company_code=? AND owner_kind=? AND owner_id=? FOR UPDATE",c,w.get("owner_kind"),w.get("owner_id"));require(lease.equals(current.get("lease_token")),"退货查询更新租约已变化");}
            for(String kind:Arrays.asList("REFUND","EXCHANGE")){Set<Long> ids="REFUND".equals(kind)?refunds:exchanges;if(ids.isEmpty())continue;List<Object> a=args(c,ids);a.add(1,kind);String where=" WHERE company_code=? AND owner_kind=? AND owner_id IN ("+marks(ids)+")";repository.db().update("DELETE FROM oms_return_query_number"+where,a.toArray());repository.db().update("DELETE FROM oms_return_query_row"+where,a.toArray());}
            List<Object[]> values=new ArrayList<>(),numbers=new ArrayList<>();Set<String> seen=new HashSet<>();for(Map<String,Object> row:rows){Object[] v=new Object[FIELDS.size()];for(int i=0;i<v.length;i++)v[i]=row.get(FIELDS.get(i));values.add(v);indexNumbers(row,numbers,seen);}
            if(!values.isEmpty())repository.db().batchUpdate("INSERT INTO oms_return_query_row("+String.join(",",FIELDS)+") VALUES ("+marks(FIELDS)+")",values);
            if(!numbers.isEmpty())repository.db().batchUpdate("INSERT IGNORE INTO oms_return_query_number(company_code,view_kind,group_key,owner_kind,owner_id,number_type,number_value) VALUES (?,?,?,?,?,?,?)",numbers);
            for(Map<String,Object> w:claimed){int deleted=repository.db().update("DELETE FROM oms_return_query_dirty WHERE company_code=? AND owner_kind=? AND owner_id=? AND work_version=? AND lease_token=?",c,w.get("owner_kind"),w.get("owner_id"),w.get("work_version"),lease);if(deleted==0)repository.db().update("UPDATE oms_return_query_dirty SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND owner_kind=? AND owner_id=? AND lease_token=?",c,w.get("owner_kind"),w.get("owner_id"),lease);}return null;
        });
    }
    private void refundTasks(String c,Set<Long> ids,List<Map<String,Object>> out){
        List<Object> a=args(c,ids);Map<Long,Map<String,Object>> parents=new HashMap<>();for(Map<String,Object> b:repository.db().query("SELECT b.*,o.order_sn,p.dispute_type,p.payload platform_payload FROM oms_refund b JOIN oms_order o ON o.company_code=b.company_code AND o.id=b.order_id JOIN oms_platform_refund p ON p.company_code=b.company_code AND p.id=b.platform_refund_id WHERE b.company_code=? AND b.id IN ("+marks(ids)+")",ROW,a.toArray()))parents.put(number(b,"id"),b);
        Set<Long> planned=new HashSet<>();List<Map<String,Object>> plans=repository.db().query("SELECT rp.*,"+RefundReturnSummary.pending("rp")+" pending_issue,COALESCE(sl.goods_name,ol.goods_name) goods_name,IF(ol.stocked_bundle_snapshot IS NULL OR sl.sku_sn<>ol.sku_sn,'件','套') physical_unit,sh.shipment_sn actual_shipment,sh.id actual_shipment_id FROM oms_refund_return_plan rp LEFT JOIN oms_order_shipment_line sl ON sl.company_code=rp.company_code AND sl.id=rp.shipment_line_id LEFT JOIN oms_order_line ol ON ol.company_code=sl.company_code AND ol.id=sl.order_line_id LEFT JOIN oms_order_shipment sh ON sh.company_code=sl.company_code AND sh.id=sl.shipment_id WHERE rp.company_code=? AND rp.refund_id IN ("+marks(ids)+") ORDER BY rp.id LIMIT 2001",ROW,a.toArray());require(plans.size()<=2000,"退回计划过多，暂不能重建当前查询批次");
        for(Map<String,Object> p:plans){Map<String,Object> b=parents.get(number(p,"refund_id"));if(b==null)continue;if(p.get("gift_plan_id")==null)planned.add(number(b,"id"));Map<String,Object> t=base("REFUND",b,"R:"+p.get("id"));Map<String,Object> logistics=RefundValues.parse(text(b,"platform_payload"));t.putAll(map("source_id",p.get("id"),"sku_sn",p.get("sku_sn"),"goods_name",text(p,"goods_name"),"unit",p.get("physical_unit"),"is_gift",p.get("gift_plan_id")==null?0:1,"return_mode",p.get("return_mode"),"quantity",p.get("quantity"),"accepted_quantity",p.get("accepted_quantity"),"posted_quantity",p.get("posted_quantity"),"waived_quantity",p.get("waived_quantity"),"store_code",p.get("store_code"),"carrier",text(p,"return_carrier").isEmpty()?text(logistics,"company_name"):text(p,"return_carrier"),"waybill",text(p,"return_waybill").isEmpty()?text(logistics,"sid"):text(p,"return_waybill"),"original_shipment_sn",text(p,"actual_shipment"),"shipment_id",p.get("actual_shipment_id"),"create_time",p.get("create_time"),"active",Arrays.asList("CANCELED","RELEASED","STOPPED").contains(text(p,"state"))?0:1,"needs_check",number(p,"pending_issue")>0?1:0,"message",text(p,"last_error")));if(!"CLOSED".equals(text(p,"state"))&&("NEED_CHECK".equals(text(p,"parcel_state"))||"WAREHOUSE_CHECK".equals(text(p,"parcel_resolution"))))t.put("needs_check",1);out.add(t);}
        List<Map<String,Object>> scopes=repository.db().query("SELECT g.*,ol.sku_sn,COALESCE(sl.goods_name,ol.goods_name) goods_name,IF(ol.stocked_bundle_snapshot IS NULL OR sl.sku_sn<>ol.sku_sn,'件','套') physical_unit,s.shipment_sn actual_shipment,s.id actual_shipment_id FROM oms_refund_goods_task g JOIN oms_order_line ol ON ol.company_code=g.company_code AND ol.id=g.order_line_id LEFT JOIN oms_order_shipment_line sl ON sl.company_code=g.company_code AND sl.id=g.shipment_line_id LEFT JOIN oms_order_shipment s ON s.company_code=sl.company_code AND s.id=sl.shipment_id WHERE g.company_code=? AND g.refund_id IN ("+marks(ids)+") AND g.return_plan_id IS NULL AND g.action IN ('RETURN','INTERCEPT','REFUSAL') AND g.state<>'CANCELED' ORDER BY g.id LIMIT 2001",ROW,a.toArray());require(scopes.size()<=2000,"待建退回安排过多");
        for(Map<String,Object> g:scopes){Map<String,Object> b=parents.get(number(g,"refund_id"));if(b==null)continue;planned.add(number(b,"id"));Map<String,Object> t=base("REFUND",b,"G:"+g.get("id")),input=object(g.get("plan_input"));t.putAll(map("sku_sn",g.get("sku_sn"),"goods_name",g.get("goods_name"),"unit",g.get("physical_unit"),"return_mode",g.get("action"),"quantity",g.get("quantity"),"store_code",text(input,"store_code"),"original_shipment_sn",text(g,"actual_shipment"),"shipment_id",g.get("actual_shipment_id"),"create_time",g.get("create_time"),"needs_check",Arrays.asList("MANUAL","UNKNOWN","FAILED").contains(text(g,"state"))?1:0,"message",text(g,"result_message")));out.add(t);}
        for(Map<String,Object> b:parents.values())if(!planned.contains(number(b,"id"))&&"APPROVED".equals(text(b,"review_state"))&&Arrays.asList("RETURN","REFUSAL","INTERCEPT").contains(text(b,"goods_action"))&&!Arrays.asList("CLOSED","CANCELED").contains(text(b,"state"))){Map<String,Object> t=base("REFUND",b,"RI:"+b.get("id"));t.putAll(map("quantity_known",0,"return_mode",b.get("goods_action"),"message","已确认需要退回，等待明确实际商品范围并建立退回安排"));out.add(t);}
    }
    private void exchangeTasks(String c,Set<Long> ids,List<Map<String,Object>> out){
        for(Map<String,Object> e:repository.db().query("SELECT e.*,o.order_sn,COALESCE(sl.goods_name,ol.goods_name) goods_name,IF(ol.stocked_bundle_snapshot IS NULL OR sl.sku_sn<>ol.sku_sn,'件','套') physical_unit,sl.shipment_id,sh.shipment_sn actual_shipment FROM oms_exchange e JOIN oms_order o ON o.company_code=e.company_code AND o.id=e.order_id LEFT JOIN oms_order_line ol ON ol.company_code=e.company_code AND ol.id=e.order_line_id LEFT JOIN oms_order_shipment_line sl ON sl.company_code=e.company_code AND sl.id=e.source_shipment_line_id LEFT JOIN oms_order_shipment sh ON sh.company_code=sl.company_code AND sh.id=sl.shipment_id WHERE e.company_code=? AND e.id IN ("+marks(ids)+") AND e.fulfillment_mode='RETURN' AND e.linked_exchange_id IS NULL AND (e.approved_version IS NOT NULL OR e.return_result IS NOT NULL)",ROW,args(c,ids).toArray())){
            Map<String,Object> t=base("EXCHANGE",e,"E:"+e.get("id"));t.putAll(map("source_id",e.get("id"),"sku_sn",text(e,"original_sku"),"goods_name",text(e,"goods_name"),"unit",e.get("physical_unit"),"quantity",e.get("requested_quantity"),"original_shipment_sn",text(e,"actual_shipment"),"shipment_id",e.get("shipment_id"),"store_code",text(e,"return_store"),"active",Arrays.asList("CANCELED","REJECTED","CLOSED").contains(text(e,"state"))?0:1,"needs_check",Arrays.asList("ISSUE").contains(text(e,"return_qc"))?1:0,"message",text(e,"problem_message")));
            Map<String,Object> payload=object(e.get("payload"));t.put("carrier",text(payload,"buyer_logistic_name"));t.put("waybill",text(payload,"buyer_logistic_no"));Object logistics=e.get("return_logistics");if(logistics!=null){try{List<Map<String,Object>> ls=logistics instanceof List?maps(logistics):JSON.readValue(logistics.toString(),List.class);if(!ls.isEmpty()){t.put("carrier",text(ls.get(ls.size()-1),"carrier"));t.put("waybill",text(ls.get(ls.size()-1),"tracking_no"));}}catch(Exception ignored){t.put("needs_check",1);}}out.add(t);
        }
    }
    private void attachOutbound(String c,List<Map<String,Object>> tasks){Set<Long> ids=new LinkedHashSet<>();for(Map<String,Object> t:tasks)if(number(t,"shipment_id")>0)ids.add(number(t,"shipment_id"));if(ids.isEmpty())return;Map<Long,List<String>> by=new HashMap<>();for(Map<String,Object> p:repository.db().query("SELECT shipment_id,express_code FROM oms_order_shipment_package WHERE company_code=? AND shipment_id IN ("+marks(ids)+") ORDER BY id",ROW,args(c,ids).toArray()))by.computeIfAbsent(number(p,"shipment_id"),k->new ArrayList<>()).add(text(p,"express_code"));for(Map<String,Object> t:tasks)t.put("outbound_waybills",String.join(",",by.getOrDefault(number(t,"shipment_id"),Collections.emptyList())));}
    private Map<String,Object> base(String kind,Map<String,Object> b,String key){return map("owner_kind",kind,"owner_id",b.get("id"),"owner_sn",b.get("REFUND".equals(kind)?"refund_sn":"exchange_sn"),"source_key",key,"source_id",0,"channel_id",b.get("channel_id"),"order_id",b.get("order_id"),"order_sn",b.get("order_sn"),"platform_tid",b.get("platform_tid"),"platform_oid",b.get("platform_oid"),"sku_sn","","goods_name","待明确实际退回商品","unit","件","is_gift",0,"refund_only","REFUND".equals(text(b,"dispute_type"))?1:0,"return_mode","RETURN","quantity",0,"quantity_known",1,"accepted_quantity",0,"posted_quantity",0,"waived_quantity",0,"pending_count",0,"needs_check",0,"active",1,"dispatched",0,"warehouse_state","UNSENT","interaction_result","","receipt_difference",0,"expected_members",1,"message","","store_code","","carrier","","waybill","","original_shipment_sn","","outbound_waybills","","create_time",b.get("create_time"),"platform_source_sn",b.get("REFUND".equals(kind)?"refund_id":"dispute_id"));}
    void project(String c,Map<String,Object> task,List<Map<String,Object>> ledgers,List<Map<String,Object>> rows){
        Map<String,Object> t=new LinkedHashMap<>(task);t.putAll(map("company_code",c,"view_kind","TASK","group_key",task.get("source_key"),"part_key","TASK","real_store_code","","owner_code","","parcel_key","","parcel_sn","","return_sn","","ticket_id",null,"dispatch_after",null));
        if(!ledgers.isEmpty()){
            long accepted=0,posted=0;for(Map<String,Object> w:ledgers){accepted+=number(w,"accepted_quantity");posted+=number(w,"posted_quantity");}t.put("accepted_quantity",accepted);t.put("posted_quantity",posted);
            Map<String,Object> latest=ledgers.get(ledgers.size()-1);copyWarehouse(t,latest);if("CONFIRMED".equals(text(latest,"cancel_state")))t.put("active",0);
            for(Map<String,Object> w:ledgers){Map<String,Object> part=new LinkedHashMap<>(t);copyWarehouse(part,w);part.putAll(map("part_key",w.get("part_key"),"quantity",w.get("quantity"),"accepted_quantity",w.get("accepted_quantity"),"posted_quantity",w.get("posted_quantity"),"waived_quantity",0,"active","CONFIRMED".equals(text(w,"cancel_state"))?0:1,"needs_check",0));issues(part,w);part.put("snapshot",encode(w));String parcel=text(part,"parcel_key");if(parcel.isEmpty()&&!text(part,"waybill").isEmpty())parcel="INDEPENDENT:"+w.get("part_key");if(!parcel.isEmpty()){Map<String,Object> p=new LinkedHashMap<>(part);p.putAll(map("view_kind","PARCEL","group_key",parcel,"parcel_key",parcel,"create_time",w.get("parcel_created"),"quantity",Math.max(number(w,"accepted_quantity"),number(w,"quantity")-number(w,"cancelled_quantity"))));rows.add(p);}if(!text(part,"return_sn").isEmpty()){Map<String,Object> d=new LinkedHashMap<>(part);d.putAll(map("view_kind","DOCUMENT","group_key",part.get("return_sn"),"create_time",w.get("document_created")));rows.add(d);}}
            issues(t,latest);t.put("snapshot",encode(latest));
        }else{t.put("snapshot","{}");if(!text(t,"waybill").isEmpty())t.put("message",text(t,"message").isEmpty()?"已有退回物流，等待建立实际退回仓单":t.get("message"));}
        rows.add(t);
    }
    private void copyWarehouse(Map<String,Object> target,Map<String,Object> w){for(String k:Arrays.asList("store_code","real_store_code","owner_code","original_shipment_sn","parcel_key","parcel_sn","return_sn","ticket_id","dispatch_after","expected_members","pending_count"))target.put(k,w.get(k));for(String k:Arrays.asList("carrier","waybill"))if(!text(w,k).isEmpty())target.put(k,w.get(k));target.put("warehouse_state",text(w,"warehouse_state").isEmpty()?"UNSENT":text(w,"warehouse_state"));target.put("interaction_result",w.get("interaction")==null?"":text(object(w.get("interaction")),"result"));target.put("receipt_difference",number(w,"receipt_difference"));target.put("dispatched","ACCEPTED".equals(text(w,"dispatch_state"))?1:0);}
    private void issues(Map<String,Object> target,Map<String,Object> w){if(number(w,"receipt_difference")>0||number(w,"source_pending")>0||number(w,"pending_count")>0||Arrays.asList("FAILED","UNKNOWN").contains(text(w,"dispatch_state"))||Arrays.asList("PENDING","UNKNOWN","REJECTED").contains(text(w,"cancel_state"))||!text(w,"last_error").isEmpty())target.put("needs_check",1);if(!text(w,"last_error").isEmpty())target.put("message",w.get("last_error"));}
    private void indexNumbers(Map<String,Object> row,List<Object[]> out,Set<String> seen){Map<String,String> names=mapStrings("OWNER","owner_sn","ORDER","order_sn","TID","platform_tid","OID","platform_oid","SHIPMENT","original_shipment_sn","WAYBILL","waybill","PARCEL","parcel_sn","DOCUMENT","return_sn","PLATFORM_AFTERSALE","platform_source_sn");for(Map.Entry<String,String> e:names.entrySet())addNumber(row,e.getKey(),text(row,e.getValue()),out,seen);for(String s:text(row,"outbound_waybills").split(","))addNumber(row,"OUTBOUND_WAYBILL",s,out,seen);}
    private Map<String,String> mapStrings(String... v){Map<String,String> m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put(v[i],v[i+1]);return m;}
    private void addNumber(Map<String,Object> row,String kind,String value,List<Object[]> out,Set<String> seen){if(value.isEmpty())return;require(value.length()<=128,"退货查询单号长度异常");String key=row.get("view_kind")+"/"+row.get("group_key")+"/"+row.get("owner_kind")+"/"+row.get("owner_id")+"/"+kind+"/"+value;if(seen.add(key))out.add(new Object[]{row.get("company_code"),row.get("view_kind"),row.get("group_key"),row.get("owner_kind"),row.get("owner_id"),kind,value});}
}
